            { "Scene上のアバターを指定してください。", "Specify an avatar in the scene." }, { "VRCAvatarDescriptorが見つかりません。", "VRCAvatarDescriptor not found." }, { "Modular AvatarのMA Merge Animatorが必要です。", "A Modular Avatar MA Merge Animator is required." },
            { "Modular Avatarの設定が対応していません: ", "This Modular Avatar setting is unsupported: " }, { "適用先と同名のオブジェクトがあります。自動で変更できません。", "An object with the same name exists at the target. It cannot be changed automatically." },
            { "別のMA Merge AnimatorがFXをReplaceしています: ", "Another MA Merge Animator is replacing FX: " }, { "別のMA FXが顔のBlendShapeを操作しています: ", "Another MA FX controls face BlendShapes: " }, { "別のMA FXがGestureパラメーターをInt以外で定義しています: ", "Another MA FX defines a Gesture parameter as a non-Int type: " },
